create policy "reportupdates_read"
on "public"."reportUpdates"
as permissive
for select
to authenticated
using ((isuseradmin(auth.uid()) OR ((((((getuserpermissionsobject(auth.uid(), 'userReports'::text))::json #> '{default}'::text[]) ->> 'read'::text))::boolean AND ((auth.uid() = "user") OR (getreporterbyreportid(report) = auth.uid()))) OR (((((getuserpermissionsobject(auth.uid(), 'organisationReports'::text))::json #> '{default}'::text[]) ->> 'read'::text))::boolean AND isuserinorg(getorgbyreportid(report), auth.uid())))));


create policy "reports_read"
on "public"."reports"
as permissive
for select
to authenticated
using ((isuseradmin(auth.uid()) OR (((reporter = auth.uid()) AND ((((getuserpermissionsobject(auth.uid(), 'userReports'::text))::json #> '{default}'::text[]) ->> 'read'::text))::boolean) OR (isuserinorg(organisation, auth.uid()) AND ((((getuserpermissionsobject(auth.uid(), 'organisationReports'::text))::json #> '{default}'::text[]) ->> 'read'::text))::boolean))));


create policy "userprofiles_read"
on "public"."userProfiles"
as permissive
for select
to authenticated
using ((isuseradmin(auth.uid()) OR (isuserinorg(organisation, auth.uid()) AND ((id = auth.uid()) OR ((((getuserpermissionsobject(auth.uid(), 'userSearch'::text))::json #> '{default}'::text[]) ->> 'read'::text))::boolean OR ((((getuserpermissionsobject(auth.uid(), 'userManagement'::text))::json #> '{users}'::text[]) ->> 'read'::text))::boolean))));


create policy "userstructures_read"
on "public"."userStructures"
as permissive
for select
to authenticated
using ((isuseradmin(auth.uid()) OR (isuserinorg(getorgbyuserid(id), auth.uid()) AND ((id = auth.uid()) OR ((((getuserpermissionsobject(auth.uid(), 'userSearch'::text))::json #> '{default}'::text[]) ->> 'read'::text))::boolean OR ((((getuserpermissionsobject(auth.uid(), 'userManagement'::text))::json #> '{users}'::text[]) ->> 'read'::text))::boolean))));


create policy "users_read"
on "public"."users"
as permissive
for select
to authenticated
using ((isuseradmin(auth.uid()) OR (isuserinorg(organisation, auth.uid()) AND ((id = auth.uid()) OR ((((getuserpermissionsobject(auth.uid(), 'userSearch'::text))::json #> '{default}'::text[]) ->> 'read'::text))::boolean OR ((((getuserpermissionsobject(auth.uid(), 'userManagement'::text))::json #> '{users}'::text[]) ->> 'read'::text))::boolean))));
